import React from "react";
import { avatarColor, initials } from "../utils/helpers";

export default function Avatar({ name = "", size = "md", online = false, square = false }) {
  const sizes = { sm: "w-8 h-8 text-xs", md: "w-10 h-10 text-sm", lg: "w-11 h-11 text-base" };
  const dotSizes = { sm: "w-2 h-2", md: "w-2.5 h-2.5", lg: "w-3 h-3" };
  return (
    <div className="relative flex-shrink-0">
      <div
        className={`${sizes[size]} ${avatarColor(name)} font-display font-bold flex items-center justify-center
          ${square ? "rounded-xl" : "rounded-full"} select-none`}
      >
        {initials(name)}
      </div>
      {online && (
        <span
          className={`absolute bottom-0 right-0 ${dotSizes[size]} bg-crisp-green rounded-full
            border-2 border-crisp-surface`}
        />
      )}
    </div>
  );
}
